package com.ellenco.platform.controllers;
import com.ellenco.platform.auth.User;import com.ellenco.platform.domain.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
@RestController @RequestMapping("/api/inventory/counts") @PreAuthorize("hasAnyRole('ADMIN','SUPERVISOR')") public class InventoryCountController{
 private final InventoryCountRepository counts;private final InventoryCountItemRepository items;private final WarehouseRepository warehouses;private final StockBalanceRepository balances;private final AuditService audit;
 public InventoryCountController(InventoryCountRepository c,InventoryCountItemRepository i,WarehouseRepository w,StockBalanceRepository b,AuditService a){counts=c;items=i;warehouses=w;balances=b;audit=a;}
 @GetMapping public List<InventoryCount> list(){return counts.findAllByOrderByIniciadoEmDesc();}
 @PostMapping @Transactional public InventoryCount start(@RequestBody Map<String,Object> body,@AuthenticationPrincipal User user){Long wid=Long.valueOf(body.get("galpaoId").toString());Warehouse w=warehouses.findById(wid).orElseThrow(()->new IllegalArgumentException("Almoxarifado não encontrado."));InventoryCount c=new InventoryCount();c.setGalpao(w);c.setResponsavel(user.getNome());c.setContagemCega(!Boolean.FALSE.equals(body.get("contagemCega")));c=counts.save(c);for(StockBalance b:balances.findByGalpaoIdOrderByProdutoNomeAsc(wid)){InventoryCountItem i=new InventoryCountItem();i.setInventario(c);i.setSaldo(b);i.setSaldoSistema(b.getQuantidadeAtual());items.save(i);c.getItens().add(i);}audit.log(user.getNome(),user.getEmail(),"INVENTARIO","INICIO","InventoryCount",c.getId().toString(),"Inventário iniciado em "+w.getNome());return counts.save(c);}
 @PatchMapping("/{countId}/items/{itemId}") @Transactional public InventoryCountItem count(@PathVariable Long countId,@PathVariable Long itemId,@RequestBody Map<String,Object> body){InventoryCount c=counts.findById(countId).orElseThrow(()->new IllegalArgumentException("Inventário não encontrado."));if(!"EM_CONTAGEM".equals(c.getStatus()))throw new IllegalArgumentException("Inventário não está aberto para contagem.");InventoryCountItem i=items.findById(itemId).orElseThrow(()->new IllegalArgumentException("Item não encontrado."));BigDecimal q=new BigDecimal(body.get("quantidadeContada").toString());if(q.signum()<0)throw new IllegalArgumentException("Quantidade inválida.");i.setQuantidadeContada(q);i.setDivergencia(q.subtract(i.getSaldoSistema()));i.setMotivo((String)body.get("motivo"));i.setContado(true);return items.save(i);}
 @PostMapping("/{id}/submit") @Transactional public InventoryCount submit(@PathVariable Long id){InventoryCount c=counts.findById(id).orElseThrow(()->new IllegalArgumentException("Inventário não encontrado."));if(c.getItens().stream().anyMatch(i->!i.isContado()))throw new IllegalArgumentException("Todos os itens precisam ser contados.");c.setStatus("AGUARDANDO_APROVACAO");c.setEnviadoEm(LocalDateTime.now());return counts.save(c);}
 @PostMapping("/{id}/approve") @PreAuthorize("hasRole('ADMIN')") @Transactional public InventoryCount approve(@PathVariable Long id,@AuthenticationPrincipal User user){InventoryCount c=counts.findById(id).orElseThrow(()->new IllegalArgumentException("Inventário não encontrado."));if(!"AGUARDANDO_APROVACAO".equals(c.getStatus()))throw new IllegalArgumentException("Inventário não aguarda aprovação.");for(InventoryCountItem i:c.getItens()){if(i.getDivergencia().signum()!=0&&i.getMotivo()!=null&&!i.getMotivo().isBlank()){i.getSaldo().setQuantidadeAtual(i.getQuantidadeContada());balances.save(i.getSaldo());}else if(i.getDivergencia().signum()!=0)throw new IllegalArgumentException("Divergências exigem justificativa.");}c.setStatus("APROVADO");c.setAprovadoEm(LocalDateTime.now());c.setAprovadoPor(user.getNome());audit.log(user.getNome(),user.getEmail(),"INVENTARIO","APROVACAO","InventoryCount",id.toString(),"Ajustes aprovados");return counts.save(c);}
}
